WITH with_latest AS (SELECT s.*, top1.balance, top1.account_opened_date FROM customers s JOIN LATERAL (SELECT c.balance, c.opened_date AS account_opened_date FROM accounts c WHERE c.customer_id = s.id ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END AS age_tier, segment, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count, PERCENTILE_APPROX(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, APPROX_PERCENTILE(credit_limit, 0.5) AS credit_limit_p50 FROM with_latest GROUP BY CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END, segment ORDER BY consumer_count DESC;
